def _nice(x):
    import math
    if x <= 0.0:
        return 0.01
    e = math.floor(math.log10(x))
    m = x / (10.0 ** e)
    if m < 1.5:
        q = 1.0
    elif m < 3.5:
        q = 2.0
    elif m < 7.5:
        q = 5.0
    else:
        q = 10.0
    return q * (10.0 ** e)


def family_init(ctx):
    import bisect
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    v = [float(b.get("v") or 0.0) for b in bars]

    L = int(ctx.p.vol_win)
    med = [None] * n
    win = []
    for t in range(n):
        if t >= 1:
            bisect.insort(win, v[t - 1])
            if len(win) > L:
                old = v[t - 1 - L]
                k = bisect.bisect_left(win, old)
                if k < len(win) and win[k] == old:
                    del win[k]
            if len(win) >= L:
                m = len(win)
                med[t] = win[m // 2] if m % 2 else 0.5 * (win[m // 2 - 1] + win[m // 2])
    ctx.medv = med

    P = int(ctx.p.px_win)
    G = [None] * n
    run = 0.0
    for t in range(n):
        run += c[t]
        if t >= P:
            run -= c[t - P]
        k = min(t + 1, P)
        if k >= 20:
            G[t] = _nice(float(ctx.p.g_frac) * (run / k))
    ctx.G = G

    rth = [True] * n
    eod = [False] * n
    for t in range(n):
        ts = str(bars[t].get("t") or "")
        hh = -1
        mm = 0
        if len(ts) >= 16 and ts[10:11] == "T":
            try:
                hh = int(ts[11:13])
                mm = int(ts[14:16])
            except Exception:
                hh = -1
        if hh >= 0:
            mins = hh * 60 + mm
            rth[t] = (13 * 60 + 30) <= mins <= (19 * 60 + 45)
            eod[t] = mins >= (19 * 60 + 50)
    ctx.rth = rth
    ctx.eod = eod
    ctx.start = max(L, 21) + 2


def signal(ctx, i):
    import math
    if i < ctx.start:
        return 0
    if ctx.p.rth_only and not ctx.rth[i]:
        return 0
    mv = ctx.medv[i]
    g = ctx.G[i]
    if mv is None or mv <= 0.0 or g is None or g <= 0.0:
        return 0
    if ctx.v[i] < float(ctx.p.vol_mult) * mv:
        return 0
    c0, c1 = ctx.c[i], ctx.c[i - 1]
    b = float(ctx.p.band) * g
    lo = math.floor(c0 / g) * g
    hi = lo + g
    if c0 > lo and (c0 - lo) <= b and c1 <= lo:
        return 1
    if c0 < hi and (hi - c0) <= b and c1 >= hi:
        return -1
    return 0


def exit_signal(ctx, i):
    import math
    if not ctx.positions:
        return False
    if ctx.p.rth_only and ctx.eod[i]:
        return True
    j = ctx.positions[0]["entry_i"] - 1
    if j < 0:
        return False
    g = ctx.G[j]
    if g is None or g <= 0.0:
        return False
    lo = math.floor(ctx.c[j] / g) * g
    t = float(ctx.p.tgt) * g
    d = ctx._dir
    if d > 0:
        return ctx.c[i] >= lo + t
    if d < 0:
        return ctx.c[i] <= (lo + g) - t
    return False
